input.content:
const {chromium} = require('playwright');

const BASE = 'http://localhost:6006';

const STORIES = {
  success: 'elements-zimminlinemessage--success',
  warning: 'elements-zimminlinemessage--warning',
  maxQuantity: 'elements-zimminlinemessage--max-quantity-reached',
  withDiscountLabel: 'commerce-productitem--with-discount-label',
};

function iframeUrl(id) {
  return `${BASE}/iframe.html?id=${id}&viewMode=story`;
}

async function findByText(page, text) {
  // Find the deepest element whose direct text content contains the string
  return page.evaluateHandle((searchText) => {
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    let node;
    let match = null;
    while ((node = walker.nextNode())) {
      if (node.textContent && node.textContent.includes(searchText)) {
        match = node.parentElement;
        break;
      }
    }
    return match;
  }, text);
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({viewport: {width: 1280, height: 900}});
  const report = {};

  // --- 1. Success story ---
  {
    const url = iframeUrl(STORIES.success);
    const resp = await page.goto(url, {waitUntil: 'networkidle'});
    report.successStory = {url, status: resp ? resp.status() : null};

    const textEl = await findByText(page, '20% off applied');
    const textElExists = await textEl.evaluate((el) => !!el).catch(() => false);
    report.successStory.textElementFound = textElExists;

    if (textElExists) {
      const styles = await textEl.evaluate((el) => {
        const own = window.getComputedStyle(el);
        const parent = el.parentElement ? window.getComputedStyle(el.parentElement) : null;
        return {
          ownColor: own.color,
          ownFontWeight: own.fontWeight,
          ownTag: el.tagName,
          ownOuterHTMLSnippet: el.outerHTML.slice(0, 300),
          parentColor: parent ? parent.color : null,
          parentFontWeight: parent ? parent.fontWeight : null,
          parentTag: el.parentElement ? el.parentElement.tagName : null,
        };
      });
      report.successStory.styles = styles;

      // Find nearest ancestor with data-testid="zimm-inline-message" (or similar) and check for svg
      const svgCheck = await textEl.evaluate((el) => {
        let cur = el;
        let container = null;
        while (cur) {
          if (cur.dataset && (cur.dataset.testid === 'zimm-inline-message' || (cur.getAttribute && cur.getAttribute('data-testid') === 'zimm-inline-message'))) {
            container = cur;
            break;
          }
          cur = cur.parentElement;
        }
        // fallback: search whole document body for any element with data-testid containing 'inline-message'
        let containerAttr = null;
        if (!container) {
          const candidate = document.querySelector('[data-testid*="inline-message"]');
          if (candidate) {
            container = candidate;
            containerAttr = candidate.getAttribute('data-testid');
          }
        } else {
          containerAttr = container.getAttribute('data-testid');
        }
        if (!container) {
          return {containerFound: false};
        }
        const svgs = container.querySelectorAll('svg');
        return {
          containerFound: true,
          containerAttr,
          containerOuterHTMLSnippet: container.outerHTML.slice(0, 500),
          svgCount: svgs.length,
        };
      });
      report.successStory.svgCheck = svgCheck;
    }
  }

  // --- 4. Warning story (contrast/falsification check) ---
  {
    const url = iframeUrl(STORIES.warning);
    const resp = await page.goto(url, {waitUntil: 'networkidle'});
    report.warningStory = {url, status: resp ? resp.status() : null};

    // Need to know the warning story's text. Let's grab full body text content to locate the message text node.
    const bodyText = await page.evaluate(() => document.body.textContent.trim());
    report.warningStory.bodyText = bodyText;

    // Find the element containing the bulk of visible text (best-effort: the deepest element with the longest own text)
    const styles = await page.evaluate(() => {
      // find all elements with data-testid containing 'inline-message'
      const container = document.querySelector('[data-testid*="inline-message"]');
      if (!container) return {containerFound: false};
      // find text node within
      const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
      let node;
      let textEl = null;
      let text = null;
      while ((node = walker.nextNode())) {
        if (node.textContent && node.textContent.trim().length > 0) {
          textEl = node.parentElement;
          text = node.textContent.trim();
          break;
        }
      }
      const containerStyle = window.getComputedStyle(container);
      const textStyle = textEl ? window.getComputedStyle(textEl) : null;
      return {
        containerFound: true,
        containerAttr: container.getAttribute('data-testid'),
        containerColor: containerStyle.color,
        containerFontWeight: containerStyle.fontWeight,
        text,
        textElColor: textStyle ? textStyle.color : null,
        textElFontWeight: textStyle ? textStyle.fontWeight : null,
      };
    });
    report.warningStory.styles = styles;
  }

  // Also grab max-quantity-reached as an extra falsification point since AC mentioned it as alt
  {
    const url = iframeUrl(STORIES.maxQuantity);
    const resp = await page.goto(url, {waitUntil: 'networkidle'});
    report.maxQuantityStory = {url, status: resp ? resp.status() : null};
    const styles = await page.evaluate(() => {
      const container = document.querySelector('[data-testid*="inline-message"]');
      if (!container) return {containerFound: false};
      const containerStyle = window.getComputedStyle(container);
      return {
        containerFound: true,
        containerAttr: container.getAttribute('data-testid'),
        containerColor: containerStyle.color,
        containerFontWeight: containerStyle.fontWeight,
        text: container.textContent.trim(),
      };
    });
    report.maxQuantityStory.styles = styles;
  }

  // --- 5. WithDiscountLabel story ---
  {
    const url = iframeUrl(STORIES.withDiscountLabel);
    const resp = await page.goto(url, {waitUntil: 'networkidle'});
    report.withDiscountLabelStory = {url, status: resp ? resp.status() : null};

    const data = await page.evaluate(() => {
      const discountEl = document.querySelector('[data-testid="zimm-discount-label"]');
      const messageEls = Array.from(document.querySelectorAll('[data-testid="zimm-inline-message"]'));
      // also try wildcard in case testid differs
      const allTestIds = Array.from(document.querySelectorAll('[data-testid]')).map((el) => el.getAttribute('data-testid'));

      const result = {allTestIds};

      if (discountEl) {
        const rect = discountEl.getBoundingClientRect();
        const style = window.getComputedStyle(discountEl);
        result.discount = {
          found: true,
          rect: {top: rect.top, y: rect.y, left: rect.left, bottom: rect.bottom, height: rect.height},
          color: style.color,
          fontWeight: style.fontWeight,
          text: discountEl.textContent.trim(),
          outerHTMLSnippet: discountEl.outerHTML.slice(0, 300),
        };
      } else {
        result.discount = {found: false};
      }

      result.messages = messageEls.map((el) => {
        const rect = el.getBoundingClientRect();
        const style = window.getComputedStyle(el);
        return {
          rect: {top: rect.top, y: rect.y, left: rect.left, bottom: rect.bottom, height: rect.height},
          color: style.color,
          fontWeight: style.fontWeight,
          text: el.textContent.trim(),
        };
      });

      return result;
    });
    report.withDiscountLabelStory.data = data;
  }

  console.log(JSON.stringify(report, null, 2));

  await browser.close();
})().catch((e) => {
  console.error('SCRIPT ERROR:', e);
  process.exit(1);
});

