const {chromium} = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

const BASE = 'http://localhost:6006';
const SHOT_DIR = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/6017b702-06fb-4295-9164-1c708495531a/scratchpad/screenshots';

async function gotoStory(page, url) {
  const resp = await page.goto(url, {waitUntil: 'domcontentloaded', timeout: 30000});
  await page.waitForSelector('#storybook-root', {timeout: 15000}).catch(() => {});
  await page.waitForFunction(
    () => {
      const root = document.querySelector('#storybook-root');
      return root && root.textContent && root.textContent.trim().length > 0;
    },
    {timeout: 15000}
  );
  await page.waitForTimeout(500);
  return resp;
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({viewport: {width: 1280, height: 900}});

  const url = `${BASE}/iframe.html?id=elements-zimminlinemessage--warning&viewMode=story`;
  await gotoStory(page, url);

  await page.screenshot({path: `${SHOT_DIR}/warning-story.png`, fullPage: true});

  // Investigate: where does the "No Preview" / controls-table text actually live? Is it visible?
  const investigation = await page.evaluate(() => {
    function isVisible(el) {
      if (!el) return false;
      const style = window.getComputedStyle(el);
      const rect = el.getBoundingClientRect();
      return (
        style.display !== 'none' &&
        style.visibility !== 'hidden' &&
        parseFloat(style.opacity) !== 0 &&
        rect.width > 0 &&
        rect.height > 0
