// Given a PNG buffer, decode it via an in-browser canvas and return the pixel
// with the lowest luminance (best proxy for "most ink coverage" / true glyph
// fill colour, since anti-aliased edges blend toward the white background).
async function sampleInkColor(page, pngBuffer) {
  const base64 = pngBuffer.toString('base64');
  return page.evaluate(async (b64) => {
    const img = new Image();
    const loaded = new Promise((resolve, reject) => {
      img.onload = resolve;
      img.onerror = reject;
    });
    img.src = 'data:image/png;base64,' + b64;
    await loaded;
    const canvas = document.createElement('canvas');
    canvas.width = img.naturalWidth;
    canvas.height = img.naturalHeight;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0);
    const {data, width, height} = ctx.getImageData(0, 0, canvas.width, canvas.height);

    let darkest = null;
    let darkestLuminance = Infinity;
